from pathlib import Path
import json,subprocess,os,time,datetime
P=Path('/home/philip/binary-eagle-decoding');R=P/'runs/design-readiness-20261104-01';C=Path(json.loads((R/'freeze.json').read_text())['output']);A=json.loads((R/'stage1-analysis.json').read_text());assert A['status']=='RAW_REQUEST_MODEL_RUNTIME_METRICS_AND_RELEASE_AUDIT_PASS'
