selection=dict(at_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),recipes=recipes,early_pooled_ranks=[(r['arm'],r['TPS']) for r in candidates],scope='Prefrozen extension rule: control + apparent fastest + apparent slowest; noisy exploratory ranks, not permanent pruning or general prediction.',parent_panel='stage1-analysis.json')
(R/'stage2-selection.json').write_text(json.dumps(selection,indent=2)+'\n');env={**os.environ,'CUDA_VISIBLE_DEVICES':'0','PYTHONDONTWRITEBYTECODE':'1','CUDA_CACHE_PATH':str(P/'runs/local-w1a8-modern-gpu-training-qualification-20261103-01/cuda'),'CUDA_CACHE_MAXSIZE':'1073741824','CUBLAS_WORKSPACE_CONFIG':':4096:8'};stages=[]
for recipe in recipes:
 argv=[str(P/'.venv/bin/python'),str(P/'scripts/design_readiness/fixed_objective.py'),'--recipe',recipe,'--final-updates','7680','--resume',str(C/(recipe+'6720')/'checkpoint-00006720.pt'),'--out',str(C/(recipe+'7680')),'--freeze',str(R/'freeze.json'),'--allow-cuda'];t=time.monotonic();child=subprocess.Popen(argv,cwd=P,env=env);q=Path('/proc')/str(child.pid);identity=dict(pid=child.pid,pgid=os.getpgid(child.pid),boot_id=Path('/proc/sys/kernel/random/boot_id').read_text().strip(),start_ticks=int((q/'stat').read_text().rsplit(')',1)[1].split()[19]),argv=argv);(R/(recipe+'7680-identity.json')).write_text(json.dumps(identity,indent=2)+'\n');code=child.wait();stages.append(dict(recipe=recipe,wall_seconds=time.monotonic()-t,exit_code=code));(R/'stage2-processes.json').write_text(json.dumps(stages,indent=2)+'\n');assert code==0
(R/'stage2-result.json').write_text(json.dumps(dict(status='THREE_EXTENSIONS_TRAINED_EXPORTED_NOT_NATIVE_ADMITTED',selection=selection,stages=stages),indent=2)+'\n')
